// Frontend-owned session metadata; does not claim native B session execution.
export function sessionFor(record){return record.session??={schema:'interaction-session-0.2',sources:[],scope:'当前截图中的可见界面与核心任务；动态行为未执行',events:[],notes:[],versions:[],checks:[]};}
export function addSource(session,url){const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw Error('请输入 http 或 https 链接');if(session.sources.some(s=>s.url===parsed.href))return;session.sources.push({id:crypto.randomUUID(),url:parsed.href,type:parsed.hostname.endsWith('figma.com')?'figma':'website',status:'not_executed',at:new Date().toISOString()});}
export function addNote(session,text,kind='statement',version=1){if(!text.trim())throw Error('请填写补充内容');session.notes.push({id:crypto.randomUUID(),text:text.trim(),kind,actor_type:'human',version,at:new Date().toISOString(),status:'pending'});}
export function recordDecision(record,issue){if(issue.reviewStatus!=='pending'&&!issue.note?.trim())throw Error('请先填写审核理由，再确认、驳回或设为待验证');const s=sessionFor(record);s.events.push({id:crypto.randomUUID(),type:'human_review',finding_id:issue.id,actor_type:'human',at:new Date().toISOString(),version:record.version,status:issue.reviewStatus,reason:issue.note||'',severity:issue.severity});}
export function checkpoint(previous,next,kind){const s=structuredClone(sessionFor(previous));s.versions.push({id:previous.id,version:previous.version,context:structuredClone(previous.context),issues:structuredClone(previous.issues),at:new Date().toISOString()});s.events.push({id:crypto.randomUUID(),type:kind,actor_type:'human',at:new Date().toISOString(),from_version:previous.version,to_version:next.version,scope:'当前截图整体重评；未执行依赖局部重查'});next.session=s;next.issues?.forEach(i=>{i.previousHumanReview={status:i.reviewStatus,note:i.note||'',severity:i.severity};i.reviewStatus=i.decision==='insufficient_evidence'?'verify':'pending';i.note='';});return next;}
export function sessionMarkdown(record){const s=sessionFor(record);return ['## 检查范围与材料',s.scope,'截图：'+(record.mode==='mock'?'模拟流程，未实际分析':record.mode==='stub'?'stub 契约验证，未实际分析':'已调用截图引擎；结果待人工核验'),...s.sources.map(x=>`- ${x.url}：未读取，仅登记`),'## 补充与未决项',...s.notes.map(x=>`- [${x.status}] ${x.text}（${x.kind} / v${x.version} / ${x.at}）`),'## 人工决定与变更',...s.events.map(x=>JSON.stringify(x)),'## 历史版本快照',...s.versions.map(x=>`- v${x.version} / ${x.id} / ${x.at} / ${x.issues.length} 项发现`)];}
